from pathlib import Path
import base64
import re

FULL_B64 = """"""
MARK_B64 = """"""

public = Path("public/highfly")
public.mkdir(parents=True, exist_ok=True)
full = base64.b64decode(FULL_B64)
mark = base64.b64decode(MARK_B64)
if not full.startswith(b"\x89PNG\r\n\x1a\n") or not mark.startswith(b"\x89PNG\r\n\x1a\n"):
    raise SystemExit("HIGHFLY logo payload is not a valid PNG signature")
(public / "highfly-logo-full.png").write_bytes(full)
(public / "highfly-logo-mark.png").write_bytes(mark)

for path in (Path("index.html"), Path("play.html")):
    text = path.read_text(encoding="utf-8")
    # Final visible-product scrub only. Donor internals/source architecture remain untouched.
    text = text.replace("World of ClaudeCraft", "HIGHFLY")
    text = text.replace("Discord", "Comunidad")
    # Repair the self-closing image syntax emitted by the previous branding pass.
    text = re.sub(
        r'<img([^>]*?)\s*/\s+data-highfly-brand-target="([^"]+)">',
        r'<img\1 data-highfly-brand-target="\2" />',
        text,
    )
    path.write_text(text, encoding="utf-8")

locale = Path("src/ui/i18n.locales/es_ES.ts")
locale_text = locale.read_text(encoding="utf-8")
locale_text = locale_text.replace("World of ClaudeCraft", "HIGHFLY").replace("Discord", "Comunidad")
locale.write_text(locale_text, encoding="utf-8")

# Runtime i18n renders the base UI catalog before/alongside locale overrides.
# Scrub only the exact donor product-name literal from UI source files so no
# visible entry/footer/onboarding surface can re-inject it after index.html was patched.
for ui_source in Path("src/ui").rglob("*.ts"):
    ui_text = ui_source.read_text(encoding="utf-8")
    if "World of ClaudeCraft" in ui_text:
        ui_source.write_text(
            ui_text.replace("World of ClaudeCraft", "HIGHFLY"),
            encoding="utf-8",
        )

print("HIGHFLY_RUN1J_J4_BRANDFIX_APPLIED=1")
